/**
 * HyperMillStrategyEngine — CAM Strategy Selector for hyperMILL Operations
 *
 * Maps part geometry type, operation goal, and material to the optimal
 * hyperMILL machining strategy. Based on hyperMILL Manual Parts 1-4
 * covering 2D, 3D, turning, and 5-axis strategies.
 *
 * Source: document:hypermill-manual-en-{1,2,3,4}
 * Generated by /pdf-learn forge-triple pipeline
 */

// ============================================================================
// TYPES
// ============================================================================

export type GeometryType =
  | "pocket_2d"
  | "contour_2d"
  | "face"
  | "slot"
  | "chamfer"
  | "freeform_3d"
  | "steep_wall"
  | "flat_area"
  | "groove"
  | "rib"
  | "corner"
  | "turning_external"
  | "turning_internal"
  | "turning_groove"
  | "thread";

export type OperationGoal = "roughing" | "finishing" | "rest_machining" | "semi_finishing";

export interface StrategyInput {
  geometryType: GeometryType;
  operationGoal: OperationGoal;
  materialGroup?: string; // ISO P/M/K/N/S/H
  toolDiameterMm?: number;
  wallAngleDeg?: number; // 0=flat, 90=vertical
  hasPreviousRoughing?: boolean;
  pocketDepthMm?: number;
  partToleranceMm?: number;
}

export interface StrategyRecommendation {
  strategyName: string;
  hyperMillCycle: string;
  description: string;
  suggestedStepdown: number | null; // factor of tool diameter
  suggestedStepover: number | null; // factor of tool diameter
  cuttingMode: "climb" | "conventional" | "zigzag";
  warnings: string[];
  confidence: number;
  source: string;
}

export interface StrategyEngineStats {
  calculations: number;
  lastInput: StrategyInput | null;
}

